const appointmentVideoDue = `-- name: AppointmentVideoDue :many
SELECT a.id, a.uuid, a.organization_id, a.type_id, a.host_user_id, a.status, a.starts_at, a.ends_at, a.buffer_before, a.buffer_after, a.timezone, a.title, a.notes, a.location_kind, a.location_value, a.video_room_uuid, a.invitee_name, a.invitee_email, a.invitee_phone, a.intake_values, a.contact_id, a.company_id, a.conversation_id, a.source, a.booked_by_user_id, a.token_version, a.sequence, a.cancel_reason, a.cancelled_by, a.cancelled_at, a.confirmed_at, a.completed_at, a.external_provider, a.external_calendar_id, a.external_event_id, a.external_synced_at, a.created_at, a.updated_at FROM appointments a
JOIN video_rooms r ON r.organization_id=a.organization_id AND r.uuid=a.video_room_uuid
WHERE a.status IN ('scheduled','confirmed') AND r.scheduled_end_at <= $1
ORDER BY a.id LIMIT 500
`

// Global minutely worker; every subsequent mutation uses the returned org.
func (q *Queries) AppointmentVideoDue(ctx context.Context, scheduledEndAt pgtype.Timestamptz) ([]Appointment, error) {
	rows, err := q.db.Query(ctx, appointmentVideoDue, scheduledEndAt)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []Appointment{}
	for rows.Next() {
		var i Appointment
		if err := rows.Scan(
			&i.ID,
			&i.Uuid,
			&i.OrganizationID,
			&i.TypeID,
			&i.HostUserID,
			&i.Status,
			&i.StartsAt,
			&i.EndsAt,
			&i.BufferBefore,
			&i.BufferAfter,
			&i.Timezone,
			&i.Title,
			&i.Notes,
			&i.LocationKind,
			&i.LocationValue,
			&i.VideoRoomUuid,
			&i.InviteeName,
			&i.InviteeEmail,
			&i.InviteePhone,
			&i.IntakeValues,
			&i.ContactID,
			&i.CompanyID,
			&i.ConversationID,
			&i.Source,
			&i.BookedByUserID,
			&i.TokenVersion,
			&i.Sequence,
			&i.CancelReason,
			&i.CancelledBy,
			&i.CancelledAt,
			&i.ConfirmedAt,
			&i.CompletedAt,
			&i.ExternalProvider,
			&i.ExternalCalendarID,
			&i.ExternalEventID,
			&i.ExternalSyncedAt,
			&i.CreatedAt,
			&i.UpdatedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

